//! Differential test against abaplint on whole files.
//!
//! Needs golden data generated by the oracle, otherwise the test is skipped:
//!   cd tools && npm ci && cd ..
//!   node tools/oracle.mjs tests/corpus/golden --list tests/corpus/corpora.txt
//!
//! Run with `cargo test -p abap-syntax --test oracle_diff -- --nocapture`
//! to see the report.
//!
//! Known differences: when a macro is defined twice, abaplint keeps the first
//! definition; we follow the ABAP documentation, a redefinition applies from
//! its position on (abap_fm_json zcl_json_handler).
//!
//! Native SQL is HANA SQL, not ABAP: where abaplint splits it into
//! statements is not compared, the HANA SQL parser reads it as text.

mod common;

use std::collections::BTreeMap;

use serde::Deserialize;

/// Baselines; raise when improving.
const MIN_TOKEN_FILES_PERCENT: f64 = 99.9;
const MIN_BOUNDARY_FILES_PERCENT: f64 = 99.5;
const MIN_KIND_PERCENT: f64 = 99.8;

#[derive(Deserialize)]
struct Golden {
    file: String,
    tokens: Vec<GoldenToken>,
    statements: Vec<GoldenStatement>,
}

#[derive(Deserialize)]
struct GoldenToken {
    text: String,
    kind: String,
    row: u32,
    col: u32,
}

#[derive(Deserialize)]
struct GoldenStatement {
    #[serde(rename = "type")]
    kind: String,
    tokens: Vec<(u32, u32)>,
}

#[test]
fn oracle_diff() {
    let root = common::repo_root();
    let files = common::json_files(&root.join("tests/corpus/golden/tests"));
    if files.is_empty() {
        println!("skipped: no golden data, see the comment at the top of this file");
        return;
    }

    let mut token_files_ok = 0;
    let mut boundary_files_ok = 0;
    let mut statements_total = 0;
    let mut kinds_ok = 0;
    let mut token_diffs = Vec::new();
    let mut boundary_diffs = Vec::new();
    let mut kind_diffs: BTreeMap<(String, String), Vec<String>> = BTreeMap::new();

    for f in &files {
        let mut golden: Golden =
            serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
        let path = root.join(&golden.file);
        let source = std::fs::read_to_string(&path).unwrap();
        // like abaplint, macros of the other files of the same object count
        let parsed = abap_syntax::parse_with_macros(&source, &common::sibling_macros(&path));
        let tokens = parsed.tokens();
        // tokens of macro expansions are not in abaplint's token list
        let real: Vec<&abap_syntax::Token> = tokens.iter().filter(|t| !t.expanded).collect();

        // tokens; comment positions are excluded, abaplint misplaces comments
        // that have trailing whitespace
        if real.len() != golden.tokens.len() {
            token_diffs.push(format!(
                "{}: {} tokens, abaplint {}",
                golden.file,
                real.len(),
                golden.tokens.len()
            ));
        } else {
            if let Some(i) = real.iter().zip(&golden.tokens).position(|(t, g)| {
                t.text != g.text
                    || t.abaplint_name() != g.kind
                    || (g.kind != "Comment" && (t.start.row, t.start.col) != (g.row, g.col))
            }) {
                let (t, g) = (real[i], &golden.tokens[i]);
                token_diffs.push(format!(
                    "{}:{}:{} {} {:?}, abaplint {} {:?} at {}:{}",
                    golden.file,
                    t.start.row,
                    t.start.col,
                    t.abaplint_name(),
                    t.text,
                    g.kind,
                    g.text,
                    g.row,
                    g.col
                ));
            } else {
                token_files_ok += 1;
            }
        }

        // statements, keyed by the position of their first token
        let ours: Vec<(Vec<(u32, u32)>, &str)> = parsed
            .statements
            .iter()
            .filter(|s| s.kind != abap_syntax::StatementKind::NativeSQL)
            .map(|s| {
                let pos = s
                    .tokens
                    .iter()
                    .map(|i| (tokens[*i].start.row, tokens[*i].start.col))
                    .collect();
                (pos, s.kind.as_str())
            })
            .collect();
        golden.statements.retain(|g| g.kind != "NativeSQL");
        let same_boundaries = ours.len() == golden.statements.len()
            && ours
                .iter()
                .zip(&golden.statements)
                .all(|((pos, _), g)| *pos == g.tokens);
        if same_boundaries {
            boundary_files_ok += 1;
        } else {
            let first_diff = ours
                .iter()
                .zip(&golden.statements)
                .position(|((pos, _), g)| *pos != g.tokens)
                .unwrap_or(ours.len().min(golden.statements.len()));
            let at = golden
                .statements
                .get(first_diff)
                .and_then(|g| g.tokens.first());
            boundary_diffs.push(format!(
                "{} near {:?}: {} statements, abaplint {}",
                golden.file,
                at,
                ours.len(),
                golden.statements.len()
            ));
        }

        // keyed by the last token, chained statements share their first tokens
        let by_pos: BTreeMap<_, _> = ours
            .iter()
            .map(|(pos, k)| (pos.last().copied(), *k))
            .collect();
        for (index, g) in golden.statements.iter().enumerate() {
            statements_total += 1;
            // same boundaries: compare in order, macro expansions share positions
            let got = if same_boundaries {
                ours[index].1
            } else {
                by_pos
                    .get(&g.tokens.last().copied())
                    .copied()
                    .unwrap_or("<missing>")
            };
            if got == g.kind {
                kinds_ok += 1;
            } else {
                let line = g.tokens.last().map(|p| p.0).unwrap_or(0) as usize;
                let text = source
                    .lines()
                    .nth(line.saturating_sub(1))
                    .unwrap_or("")
                    .trim()
                    .to_string();
                kind_diffs
                    .entry((g.kind.clone(), got.to_string()))
                    .or_default()
                    .push(format!("{}:{line}: {text}", golden.file));
            }
        }
    }

    let n = files.len();
    println!("token diffs ({}):", token_diffs.len());
    for d in token_diffs.iter().take(10) {
        println!("    {d}");
    }
    println!("boundary diffs ({}):", boundary_diffs.len());
    for d in boundary_diffs.iter().take(10) {
        println!("    {d}");
    }
    let mut kinds: Vec<_> = kind_diffs.iter().collect();
    kinds.sort_by_key(|(_, v)| std::cmp::Reverse(v.len()));
    println!("kind diffs (abaplint -> ours):");
    for ((expected, got), cases) in kinds.iter().take(30) {
        println!("  {expected} -> {got}: {}", cases.len());
        for c in cases.iter().take(2) {
            println!("      {c}");
        }
    }

    let token_rate = common::percent(token_files_ok, n);
    let boundary_rate = common::percent(boundary_files_ok, n);
    let kind_rate = common::percent(kinds_ok, statements_total);
    println!(
        "\nfiles: {n}, identical tokens: {token_rate:.1}%, identical statement boundaries: {boundary_rate:.1}%, \
         statement kinds: {kinds_ok}/{statements_total} ({kind_rate:.2}%)"
    );
    assert!(
        token_rate >= MIN_TOKEN_FILES_PERCENT,
        "token rate {token_rate:.1}%"
    );
    assert!(
        boundary_rate >= MIN_BOUNDARY_FILES_PERCENT,
        "boundary rate {boundary_rate:.1}%"
    );
    assert!(kind_rate >= MIN_KIND_PERCENT, "kind rate {kind_rate:.2}%");
}
